package dev.kelmagic.research;
import dev.kelmagic.*;import dev.kelmagic.item.CodexItem;import java.util.*;import net.minecraft.core.registries.BuiltInRegistries;import net.minecraft.resources.ResourceLocation;import net.minecraft.server.level.ServerPlayer;import net.minecraft.world.entity.player.Player;import net.minecraft.world.item.*;import net.minecraft.network.chat.Component;import net.minecraft.world.InteractionHand;import net.neoforged.neoforge.network.PacketDistributor;import net.neoforged.bus.api.SubscribeEvent;import net.neoforged.fml.common.EventBusSubscriber;
@EventBusSubscriber(modid=KelMagic.MODID)public final class Research {
 public static final net.neoforged.neoforge.registries.DeferredItem<ResearchPaperItem> HYPOTHESIS=KelMagic.ITEMS.register("research_hypothesis",()->new ResearchPaperItem(false));
 public static final net.neoforged.neoforge.registries.DeferredItem<ResearchPaperItem> DISCOVERY=KelMagic.ITEMS.register("research_discovery",()->new ResearchPaperItem(true));
 public static ResearchState CLIENT_VIEW=ResearchState.EMPTY;public static void init(){}public static ResearchState state(Player p){return p.getData(dev.kelmagic.server.MagicAttachments.RESEARCH);}
 public static String name(ResearchCatalog.Node n){if(n.id().equals("mana_potion"))return "Отзвук в склянке";if(n.id().startsWith("rite:"))return "Великое высказывание — "+n.id().substring(5);if(n.id().equals("copper_inscriptions"))return "Медная письменность";return BuiltInRegistries.ITEM.get(ResourceLocation.fromNamespaceAndPath("kelmagic",n.icon())).getDescription().getString();}
 public static void sync(ServerPlayer p){var s=state(p);PacketDistributor.sendToPlayer(p,new dev.kelmagic.network.ResearchSnapshot(s));}
 public static void save(ServerPlayer p,ResearchState s){p.setData(dev.kelmagic.server.MagicAttachments.RESEARCH,s);sync(p);}
 public static void tab(ServerPlayer p,String t){if(!state(p).tabs().contains(t))save(p,state(p).add("tabs",t));}
 public static Set<String> inventoryWords(Player p){var words=new HashSet<String>();for(var s:p.getInventory().items)if(s.getItem() instanceof CodexItem)words.addAll(CodexItem.knownWords(s));for(var s:p.getInventory().offhand)if(s.getItem() instanceof CodexItem)words.addAll(CodexItem.knownWords(s));return words;}
 public static boolean allowed(Player p,ItemStack output){if(output.isEmpty())return true;if(ResearchBrewing.magicPotion(output))return ResearchCatalog.learned(p.level().isClientSide?CLIENT_VIEW:state(p),"mana_potion");var id=BuiltInRegistries.ITEM.getKey(output.getItem());if(!id.getNamespace().equals("kelmagic"))return true;String key=id.getPath();if(Set.of("mana_core","archivists_codex","creative_codex","archivist_table").contains(key))return true;if(key.contains("inscribed_copper_")){String word=key.substring(key.indexOf("inscribed_copper_")+17);return inventoryWords(p).contains(word);}return ResearchCatalog.learned(p.level().isClientSide?CLIENT_VIEW:state(p),key);}
 public static boolean owned(ServerPlayer p,ItemStack s){return p.getUUID().toString().equals(s.getOrDefault(MagicComponents.RESEARCH_OWNER.get(),""));}
 public static boolean begin(ServerPlayer p,String id,boolean offhand,String token){var book=p.getItemInHand(offhand?InteractionHand.OFF_HAND:InteractionHand.MAIN_HAND);if(!p.isAlive()||!(book.getItem() instanceof CodexItem)||!token.equals(book.get(MagicComponents.CODEX_TOKEN.get())))return false;var n=ResearchCatalog.BY_ID.get(id);var state=state(p);if(n==null||n.free()||n.sealed()||!ResearchCatalog.visible(state,n)||ResearchCatalog.learned(state,id))return false;if((p.getOffhandItem().is(HYPOTHESIS)||p.getOffhandItem().is(DISCOVERY))&&owned(p,p.getOffhandItem())&&id.equals(p.getOffhandItem().get(MagicComponents.RESEARCH_ID.get())))return false;for(var s:p.getInventory().items)if((s.is(HYPOTHESIS)||s.is(DISCOVERY))&&owned(p,s)&&id.equals(s.get(MagicComponents.RESEARCH_ID.get())))return false;int paper=-1;for(int i=0;i<p.getInventory().items.size();i++)if(p.getInventory().items.get(i).is(Items.PAPER)){paper=i;break;}if(paper<0){p.displayClientMessage(Component.literal("Нужен один лист бумаги."),true);return false;}var sheet=HYPOTHESIS.toStack();sheet.set(MagicComponents.RESEARCH_ID.get(),id);sheet.set(MagicComponents.RESEARCH_OWNER.get(),p.getUUID().toString());var stock=p.getInventory().getItem(paper);stock.shrink(1);if(stock.isEmpty())p.getInventory().setItem(paper,sheet);else if(!p.getInventory().add(sheet))p.drop(sheet,false);save(p,state.add("started",id));p.sendSystemMessage(Component.literal("["+name(n)+"] "+n.steps().getFirst().hint()).withStyle(net.minecraft.ChatFormatting.GRAY));completePapers(p);return true;}
 public static int progress(ResearchState s,ResearchCatalog.Node n){int i=0;while(i<n.steps().size()&&s.evidence().contains(n.id()+":"+i))i++;return i;}
 public static void thought(ServerPlayer p,ResearchCatalog.Node n,int step){var st=n.steps().get(step);String value=st.comment().isBlank()?"Я заметил новый след и сохранил его на листе.":st.comment();p.sendSystemMessage(Component.literal("["+name(n)+" · "+(step+1)+"/"+n.steps().size()+"] ").withStyle(net.minecraft.ChatFormatting.DARK_AQUA).append(Component.literal(value).withStyle(net.minecraft.ChatFormatting.GRAY,net.minecraft.ChatFormatting.ITALIC)));}
 public static void observe(ServerPlayer p,String signal){var s=state(p);var messages=new ArrayList<Map.Entry<ResearchCatalog.Node,Integer>>();for(String id:s.started()){var n=ResearchCatalog.BY_ID.get(id);if(n==null||n.sealed()||ResearchCatalog.learned(s,id)||!hasPaper(p,id))continue;int step=progress(s,n);if(step<n.steps().size()){var st=n.steps().get(step);if(st.kind().equals("observation")&&st.signals().contains(signal)){s=s.add("evidence",id+":"+step);messages.add(Map.entry(n,step));}}}if(!messages.isEmpty()){save(p,s);completePapers(p);for(var m:messages)thought(p,m.getKey(),m.getValue());}}
 public static boolean hasPaper(ServerPlayer p,String id){return p.getInventory().items.stream().anyMatch(s->s.is(HYPOTHESIS)&&owned(p,s)&&id.equals(s.get(MagicComponents.RESEARCH_ID.get())))||p.getOffhandItem().is(HYPOTHESIS)&&owned(p,p.getOffhandItem())&&id.equals(p.getOffhandItem().get(MagicComponents.RESEARCH_ID.get()));}
 static List<ItemStack> stocks(ServerPlayer p){var all=new ArrayList<ItemStack>(p.getInventory().items);all.addAll(p.getInventory().offhand);return all;}
 public static boolean sample(ServerPlayer p,String id){var n=ResearchCatalog.BY_ID.get(id);var s=state(p);if(n==null||n.sealed()||!s.started().contains(id)||ResearchCatalog.learned(s,id)||!hasPaper(p,id))return false;int step=progress(s,n);if(step>=n.steps().size())return false;var st=n.steps().get(step);if(!st.kind().equals("material"))return false;var needs=new LinkedHashMap<Item,Integer>();for(String key:st.samples().isEmpty()?List.of(st.item()):st.samples()){var item=BuiltInRegistries.ITEM.get(ResourceLocation.parse(key));if(item==Items.AIR)return false;needs.merge(item,1,Integer::sum);}var stocks=stocks(p);for(var need:needs.entrySet())if(stocks.stream().filter(v->v.is(need.getKey())).mapToInt(ItemStack::getCount).sum()<need.getValue())return false;for(var need:needs.entrySet()){int left=need.getValue();for(var stack:stocks)if(stack.is(need.getKey())){int take=Math.min(left,stack.getCount());stack.shrink(take);left-=take;if(left==0)break;}}save(p,s.add("evidence",id+":"+step));completePapers(p);thought(p,n,step);p.getInventory().setChanged();return true;}
 public static boolean material(ServerPlayer p,ItemStack sheet){if(!sheet.is(HYPOTHESIS)||!owned(p,sheet))return false;return sample(p,sheet.getOrDefault(MagicComponents.RESEARCH_ID.get(),""));}
 public static boolean advanceMaterialsAtTable(ServerPlayer p){boolean pending=state(p).started().stream().anyMatch(id->{var n=ResearchCatalog.BY_ID.get(id);return n!=null&&hasPaper(p,id)&&progress(state(p),n)<n.steps().size()&&n.steps().get(progress(state(p),n)).kind().equals("material");});if(!pending)return false;boolean near=false;for(var at:net.minecraft.core.BlockPos.betweenClosed(p.blockPosition().offset(-2,-1,-2),p.blockPosition().offset(2,1,2)))if(p.serverLevel().getBlockState(at).is(MagicStudy.TABLE.get())&&p.distanceToSqr(net.minecraft.world.phys.Vec3.atCenterOf(at))<=6.25){near=true;break;}if(!near)return false;boolean changed=false;for(String id:List.copyOf(state(p).started()))changed=sample(p,id)||changed;return changed;}
 public static void completePapers(ServerPlayer p){for(int i=0;i<p.getInventory().items.size();i++)convert(p,p.getInventory().getItem(i),i);var off=p.getOffhandItem();if(done(p,off))p.setItemInHand(InteractionHand.OFF_HAND,asDiscovery(off));p.getInventory().setChanged();}
 static boolean done(ServerPlayer p,ItemStack sheet){var n=ResearchCatalog.BY_ID.get(sheet.getOrDefault(MagicComponents.RESEARCH_ID.get(),""));return sheet.is(HYPOTHESIS)&&owned(p,sheet)&&n!=null&&!n.sealed()&&state(p).started().contains(n.id())&&progress(state(p),n)==n.steps().size();}
 static ItemStack asDiscovery(ItemStack s){var out=DISCOVERY.toStack();out.set(MagicComponents.RESEARCH_ID.get(),s.get(MagicComponents.RESEARCH_ID.get()));out.set(MagicComponents.RESEARCH_OWNER.get(),s.get(MagicComponents.RESEARCH_OWNER.get()));return out;}
 static void convert(ServerPlayer p,ItemStack s,int slot){if(done(p,s))p.getInventory().setItem(slot,asDiscovery(s));}
 public static boolean apply(ServerPlayer p,ItemStack sheet){var n=ResearchCatalog.BY_ID.get(sheet.getOrDefault(MagicComponents.RESEARCH_ID.get(),""));var s=state(p);if(!sheet.is(DISCOVERY)||!owned(p,sheet)||n==null||n.sealed()||!s.started().contains(n.id())||progress(s,n)<n.steps().size()||ResearchCatalog.learned(s,n.id()))return false;grant(p,n.id());sheet.shrink(1);p.displayClientMessage(Component.literal("Открытие: "+name(n)),false);return true;}
 public static boolean grant(ServerPlayer p,String id){var n=ResearchCatalog.BY_ID.get(id);if(n==null)return false;var s=state(p).add("learned",id);if(id.equals("scripter"))s=s.add("tabs","sound");if(id.equals("magic_ingot")||id.equals("magic_cloth"))s=s.add("tabs","equipment");if(id.startsWith("rite:"))s=s.add("tabs","great");save(p,s);if(!id.startsWith("rite:"))p.awardRecipes(p.serverLevel().getRecipeManager().getRecipes().stream().filter(r->net.minecraft.core.registries.BuiltInRegistries.ITEM.getKey(r.value().getResultItem(p.registryAccess()).getItem()).equals(ResourceLocation.fromNamespaceAndPath("kelmagic",id))).toList());PacketDistributor.sendToPlayer(p,new dev.kelmagic.network.ResearchNotice(id));return true;}
 public static void status(ServerPlayer p,ItemStack sheet){var n=ResearchCatalog.BY_ID.get(sheet.getOrDefault(MagicComponents.RESEARCH_ID.get(),""));if(n==null||!owned(p,sheet))return;int step=progress(state(p),n);p.displayClientMessage(Component.literal(step<n.steps().size()?"Моя гипотеза: "+n.steps().get(step).hint():"Наблюдения завершены. Сохранить открытие ПКМ."),false);}
 @SubscribeEvent public static void crafted(net.neoforged.neoforge.event.entity.player.PlayerEvent.ItemCraftedEvent e){if(e.getEntity() instanceof ServerPlayer p){if(e.getCrafting().is(MagicContent.MANA_CORE))tab(p,"materials");boolean valid=true;if(e.getCrafting().is(Items.WHITE_WOOL)||e.getCrafting().is(Items.GOLD_NUGGET)){Item needed=e.getCrafting().is(Items.WHITE_WOOL)?Items.STRING:Items.GOLD_INGOT;int total=0;for(int i=0;i<e.getInventory().getContainerSize();i++)if(e.getInventory().getItem(i).is(needed))total+=e.getInventory().getItem(i).getCount();valid=total>=(needed==Items.STRING?4:1);}if(valid)observe(p,"craft:"+BuiltInRegistries.ITEM.getKey(e.getCrafting().getItem()));}}
 @SubscribeEvent public static void login(net.neoforged.neoforge.event.entity.player.PlayerEvent.PlayerLoggedInEvent e){if(e.getEntity() instanceof ServerPlayer p){p.resetRecipes(p.serverLevel().getRecipeManager().getRecipes().stream().filter(r->!allowed(p,r.value().getResultItem(p.registryAccess()))).toList());sync(p);}}
 @SubscribeEvent public static void respawn(net.neoforged.neoforge.event.entity.player.PlayerEvent.PlayerRespawnEvent e){if(e.getEntity() instanceof ServerPlayer p)sync(p);}
 @SubscribeEvent public static void table(net.neoforged.neoforge.event.entity.player.PlayerInteractEvent.RightClickBlock e){if(e.getEntity() instanceof ServerPlayer p&&p.level().getBlockState(e.getPos()).is(MagicStudy.TABLE.get())&&e.getItemStack().is(HYPOTHESIS)){material(p,e.getItemStack());e.setCanceled(true);e.setCancellationResult(net.minecraft.world.InteractionResult.SUCCESS);}}
 @SubscribeEvent public static void tick(net.neoforged.neoforge.event.tick.PlayerTickEvent.Post e){if(e.getEntity() instanceof ServerPlayer p&&p.tickCount%10==0){advanceMaterialsAtTable(p);if(p.containerMenu instanceof net.minecraft.world.inventory.StonecutterMenu){p.containerMenu.clickMenuButton(p,-1);p.containerMenu.broadcastChanges();}}}
 private Research(){}
}
